// Writes assets/sticker.png into src/stickerPng.ts as base64. The host only
// takes a picturePath on disk, and a bundled RN asset isn't a file path we
// can count on, so the module writes these bytes into the plugin dir.
// Run with: node scripts/embed-sticker.js (again whenever the art changes).
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const png = fs.readFileSync(path.join(root, 'assets', 'sticker.png'));
const out = path.join(root, 'src', 'stickerPng.ts');

fs.writeFileSync(
  out,
  '// Generated by scripts/embed-sticker.js from assets/sticker.png. Do not edit.\n' +
    `export const STICKER_PNG_BASE64 =\n  '${png.toString('base64')}';\n`,
);
console.log(`wrote ${out} (${png.length} bytes of png)`);
